let current='01-week';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const head=(title,desc='',kicker='')=>`<div class="heading">${kicker?`<div class="kicker">${esc(kicker)}</div>`:''}<h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div>`;
const btn=(label,page,cls='primary')=>`<button class="btn ${cls}" onclick="go('${page}')">${label}</button>`;
const chip=(label,on=false,handler="this.classList.toggle('on');this.setAttribute('aria-pressed',this.classList.contains('on'));toast('條件已調整')")=>`<button class="chip ${on?'on':''}" aria-pressed="${on}" onclick="${esc(handler)}">${on?'✓ ':''}${label}</button>`;
const progress=(step,auto=false)=>`<div class="subnav"><span class="${step===1?'current':''}">1 日期</span><i></i><span class="${step===2?'current':''}">2 ${auto?'訓練條件':'加入動作'}</span><i></i>${auto?`<span class="${step===3?'current':''}">3 身體感受</span><i></i>`:''}<span class="${step===(auto?4:3)?'current':''}">${auto?'4':'3'} 檢查</span></div>`;
function footer(label,page,meta='',sub='',disabled=false){const action=page.startsWith('!')?page.slice(1):`go('${page}')`;document.getElementById('bottom').innerHTML=`<footer class="bottom"><div class="inner ${meta?'row between':''}">${meta?`<div class="grow"><p class="strong">${meta}</p>${sub?`<p class="mini muted">${sub}</p>`:''}</div>`:''}<button class="btn primary ${meta?'':'full'}" ${disabled?'disabled':''} onclick="${esc(action)}">${label}</button></div></footer>`;}
function nav(){document.getElementById('bottom').innerHTML=`<nav class="nav"><button onclick="toast('這份原型聚焦課表流程')">${I('today')}今天</button><button class="active" onclick="go('01-week')">${I('cal')}課表</button><button onclick="toast('這份原型聚焦課表流程')">${I('list')}紀錄</button></nav>`;}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',2600);}
function go(page){current=page;const u=new URL(location);u.searchParams.set('page',page);history.replaceState({},'',u);render();window.scrollTo(0,0);}
function headerTop(back=null,label='返回'){document.getElementById('top').innerHTML=back?`<button class="back" onclick="go('${back}')">${I('back')}${label}</button>${current.startsWith('13-')||current.startsWith('14-')||current.startsWith('15')?`<button class="quiet" onclick="cancelImport()">取消${state.templateApplying?'套用':'匯入'}</button>`:'<span class="demo">設計原型</span>'}`:`<div class="brand row"><span class="iconbox">${I('today')}</span>羽球功能性健身</div><span class="demo">設計原型</span>`;}
function entries(){return `<div class="choicecards"><button class="entry" onclick="state.mode='manual';go('03-dates-manual')"><span class="iconbox">${I('edit')}</span><div class="entrycopy"><h2>手動排課</h2><p>自己挑動作、組次與日期</p></div><span class="link">開始安排 ›</span></button><button class="entry" onclick="state.mode='auto';go('03b-dates-auto')"><span class="iconbox" style="background:var(--purplebg);color:var(--indigo)">${I('spark')}</span><div class="entrycopy"><h2>自動排課</h2><p>回答問題，依條件搭配</p></div><span class="link">開始互動 ›</span></button></div>`;}
function week(empty=false){headerTop();nav();return head('本週課表','先看這週安排，再選一天查看。')+`<div class="row between" style="margin-bottom:18px"><button class="quiet" onclick="toast('切換上一週')">‹</button><span class="strong">10/19 — 10/25</span><button class="quiet" onclick="toast('切換下一週')">›</button></div>`+(empty?`<section class="card empty"><div class="iconbox">${I('cal')}</div><h2>這週還沒有課表</h2><p>自己挑動作，或讓系統陪你安排。<br>排好後都能編輯與分享。</p><button class="quiet" onclick="go('21-my-templates')">查看我的課表 ›</button></section><div class="gap">${entries()}</div><div class="card gap"><div class="row"><span class="iconbox">${I('share')}</span><div class="grow"><h3>朋友分享了課表？</h3><p class="small muted">開啟收到的連結，即可預覽與選日期匯入。</p></div></div></div>`:`${state.autoApplied?`<div class="success" style="margin-bottom:15px">✓ 已套用 ${state.applied?.length||3} 天課表，可隨時編輯。</div>`:''}${entries()}${state.draftSaved?`<button class="soft full gap" style="text-align:left" onclick="go('04-manual')"><b>繼續手動排課草稿</b><p class="small muted">${manualDays().length} 天 · 尚未套用</p></button>`:''}<div class="row between gap"><h2>這週的安排</h2><span class="small muted">${(state.applied||weekSource()).filter(d=>d.kind==='肌力').length} 肌力 · ${(state.applied||weekSource()).filter(d=>d.kind==='恢復').length} 恢復</span></div><div class="agenda gap-sm">${(state.applied||weekSource()).map(d=>[d.weekday.slice(1),Number(d.date.split('/')[1]),d.title,d.kind+' · 已安排',demoMinutes(d)]).map((d,i)=>`<button class="agenda-row ${d[4]?'':'rest'}" onclick="state.day=${i};state.readContext='saved';go('04b-day-view')"><span class="date">${d[0]}<b>${d[1]}</b></span><span class="grow"><h3>${esc(d[2])}</h3><p>${d[3]}</p></span><span class="time">${d[4]?d[4]+' 分':'—'}</span>${I('arrow')}</button>`).join('')}</div><div class="row between gap"><button class="quiet" onclick="prepareShare();go('11-share')">${I('share')} 分享這週課表</button><button class="quiet" onclick="go('21-my-templates')">${I('book')} 我的課表</button><button class="quiet" onclick="go('05-pick-strength')">${I('book')} 動作庫</button></div><button class="details-link" onclick="toast('展開目標與八區活動度安排')">查看本週重點與活動度安排 ${I('arrow')}</button>`);}
function dates(auto=false){headerTop('01-week');const picked=[...state.dates].sort((a,b)=>a-b);footer(auto?'下一步：訓練條件':`開始排 ${picked.length} 天`,auto?'08-auto-goals':'!createManualDraft()',auto?'共 7 個日期':`已選 ${picked.length} 天`,auto?'10/19 — 10/25':picked.map(n=>'10/'+n).join('、'),!auto&&!picked.length);return progress(1,auto)+head('先選要排課的日期',auto?'先圈定期間，下一步再設定球日與體能可用日。':'點選想安排的日期，可以不連續。',auto?'自動排課':'手動排課')+(auto?`<div class="card"><div class="range"><div><label class="label" for="date-from">開始日期</label><input id="date-from" class="input" type="date" value="2026-10-19"></div><div><label class="label" for="date-to">結束日期</label><input id="date-to" class="input" type="date" value="2026-10-25"></div></div><div class="soft gap small">共 7 個日期 · 稍後會區分訓練、球日恢復與休息。</div></div>`:`<div class="card calendar-card"><div class="row between"><button class="quiet" aria-label="上一個月" onclick="toast('月份切換為原型示意')">‹</button><h2>2026 年 10 月</h2><button class="quiet" aria-label="下一個月" onclick="toast('月份切換為原型示意')">›</button></div><div class="cal">${['一','二','三','四','五','六','日'].map(d=>`<span>${d}</span>`).join('')}${Array.from({length:35},(_,i)=>{const n=i-2;return n<1||n>31?'<span></span>':`<button aria-label="10月${n}日" aria-pressed="${state.dates.has(n)}" class="${state.dates.has(n)?'selected':n<19?'faded':''}" ${n<19?'disabled':''} onclick="toggleDate(${n})">${n}</button>`}).join('')}</div><div class="dates-summary">${picked.length?`✓ 已選 ${picked.length} 天：${picked.map(n=>'10/'+n).join('、')}`:'請先選至少一天'}</div></div><button class="quiet gap-sm" onclick="state.dates=new Set([19,21,23]);render()">快速選取：每週一、三、五</button>`)+`<div class="soft gap small"><b>先排成草稿，再確認套用</b><p class="muted gap-sm">選日期不會立即更動既有課表。已有訓練紀錄的日期會保留。</p></div>`;}
function toggleDate(n){state.dates.has(n)?state.dates.delete(n):state.dates.add(n);render();}
function exrows(items,phase='main',origin='manual'){return items.map((e,i)=>`<div class="exercise"><span class="count">${i+1}</span><div class="grow"><b>${esc(e[0])}</b><p>${esc(e[1])}</p></div><button class="dots" aria-label="編輯：${esc(e[0])}" onclick="openDose('${phase}',${i},'${origin}')">編輯</button></div>`).join('');}
function editor(){headerTop('01-week','課表');const ds=manualDays(),d=editorDay();footer('檢查 '+ds.length+' 天課表','10-plan-preview','目前為草稿','尚未套用到日期');return progress(2)+additionNotice()+head('手動排課','點「加入動作」挑選；點編輯或長按可改組次。')+`<div class="daytabs">${ds.map((d,i)=>`<button aria-pressed="${state.day===i}" class="${state.day===i?'on':''}" onclick="state.day=${i};render()">${d.date} ${d.weekday}<br><span class="mini">${d.kind} · ${demoMinutes(d)}分</span></button>`).join('')}</div><div class="editor-layout"><div><div class="row between" style="margin-bottom:15px"><h2>${esc(d.title)}</h2><span class="badge">${demoMinutes(d)} / 40 分鐘</span></div>${dayTemplateActions(d,'04-manual')}<div class="card"><div class="phase-title"><h2>暖身</h2><button class="quiet" aria-label="加入動作到暖身" onclick="openManualPicker('warm')">＋ 加入動作</button></div>${d.warm.length?warmRows(d.warm):'<button class="btn secondary full" onclick="addFlow()">＋ 加入每日八段動態拉伸</button>'}</div><div class="card gap-sm"><div class="phase-title"><h2>訓練</h2><button class="quiet" aria-label="加入動作到訓練" onclick="openManualPicker('main')">＋ 加入動作</button></div>${d.main.length?exrows(d.main):'<p class="small muted" style="padding:10px 0">尚未加入訓練動作，可用部位標籤快速挑選。</p>'}</div><div class="card gap-sm"><div class="phase-title"><h2>收操</h2><button class="quiet" aria-label="加入動作到收操" onclick="openManualPicker('cool')">＋ 加入動作</button></div>${d.cool.length?exrows(d.cool,'cool'):'<p class="small muted" style="padding:10px 0">尚未加入收操；依本次內容決定是否安排。</p>'}</div><div class="row between gap-sm"><button class="quiet" onclick="saveDraft()">保留草稿後離開</button><button class="quiet" onclick="openCopyDay()">複製這天</button></div><p class="mini muted">草稿會保留在這台裝置，套用前不更動正式課表。</p></div><aside class="desktop-library card"><h2>快速加入動作</h2><p class="small muted gap-sm">${d.date} ${d.weekday} · 先選要加入的階段</p><div class="stack gap">${['warm','main','cool'].map(p=>`<button class="btn secondary full" onclick="openManualPicker('${p}')">＋ 加入${phaseLabel(p)}動作</button>`).join('')}</div><div class="soft gap small">挑選器可跨部位多選、搜尋與收藏；確認後回到當天。<br>已選擇的動作會一次加入指定階段。</div></aside></div>`;}
function catalogRows(items){const day=pickerDay(),existing=new Set((day?.[state.phase]||[]).map(x=>x[0]));return items.map(e=>{const inDay=state.pickerOrigin!=='auto'&&existing.has(e.name),selected=state.selected.has(e.id);return `<div class="catalog-item"><button class="catalog-row" data-id="${e.id}" aria-label="${inDay?'已在'+phaseLabel(state.phase)+'：':selected?'取消選取：':'選取：'}${esc(e.name)}" aria-pressed="${selected}" ${inDay?'disabled':''} onclick="toggleExercise('${e.id}')"><span class="check ${selected||inDay?'checked':''}">${selected||inDay?'✓':''}</span><span class="grow"><b>${esc(e.name)}</b><span class="catalog-meta">${esc(e.tags)} · ${esc(e.equip)}</span></span><span class="mini muted">${inDay?'已加入':selected?'已選':'＋'}</span></button><button class="favorite" aria-label="${state.favorites.has(e.id)?'取消收藏':'收藏'}：${esc(e.name)}" aria-pressed="${state.favorites.has(e.id)}" onclick="toggleFavorite('${e.id}')">${state.favorites.has(e.id)?'★':'☆'}</button></div>`;}).join('');}
function toggleExercise(id){state.selected.has(id)?state.selected.delete(id):state.selected.add(id);refreshPicker(`[data-id="${id}"]`);}
function addSelected(){if(!state.selected.size)return;if(state.pickerOrigin==='auto'){state.prefs=[...state.selected];state.selected.clear();go('09-auto-body');toast('已保留偏好，預覽會交代實際採用');return;}const imported=state.pickerOrigin==='import',day=pickerDay(),target=state.phase||'main',added=[];for(const id of state.selected){const e=exercises.find(x=>x.id===id);if(e&&!day[target].some(x=>x[0]===e.name)){const row=[e.name,e.group==='strength'?'1組 × 6下':e.group==='release'?'1組 × 20秒':'1組 × 4次／側'];day[target].push(row);added.push(row);}}state.lastAddition={day,phase:target,rows:added,origin:state.pickerOrigin};state.selected.clear();go(imported?'17-import-adjust':'04-manual');toast(`${added.length} 個動作已加入${phaseLabel(target)}草稿`);}
function picker(stretch=false){const back=pickerBack(),d=pickerDay(),auto=state.pickerOrigin==='auto';headerTop(back,'取消選擇');document.querySelector('#top .back').setAttribute('onclick','cancelPicker()');pickerFooter();const kind=state.use;return head(auto?'挑選偏好動作':`加入${phaseLabel(state.phase)}動作`,auto?'可跨分類多選，最後一次確認':`${state.pickerOrigin==='import'?'副本第 '+(state.day+1)+' 天 · '+displayDate(state.mapped[state.day]):d.date+' '+d.weekday} · 選好後一次加入`)+`<div class="search picker-search">${I('search')}<input id="search" aria-label="搜尋所有動作或部位" class="input" placeholder="搜尋動作、腿拉伸、前鋸肌…" value="${esc(state.query)}" oninput="filterCatalog(this.value)"><button class="clear-search" aria-label="清除搜尋" onclick="clearPickerSearch()">×</button></div><div id="picker-browse" ${state.query?'hidden':''}><div class="segments gap-sm">${[['strength','肌力'],['stretch','動態拉伸'],['release','靜態／放鬆']].map(([v,t])=>`<button aria-pressed="${kind===v}" class="${kind===v?'on':''}" onclick="setPickerKind('${v}')">${t}</button>`).join('')}</div><div class="chips gap-sm">${(kind==='strength'?['全部','腿','胸','背','肩胛','核心','前鋸肌']:['全部','胸椎','肩胸','髖','腿部','踝小腿']).map(r=>chip(r,!state.favoritesOnly&&state.region===r,`setPickerRegion('${r}')`)).join('')}${chip('★ 收藏',state.favoritesOnly,'state.favoritesOnly=!state.favoritesOnly;refreshPicker()')}</div>${state.phase==='warm'&&kind==='stretch'&&state.pickerOrigin!=='auto'?`<div class="flow-shortcut gap-sm"><div class="grow"><b>我的每日八段暖身</b><p class="mini muted">嬰兒式、偉大拉伸、貓牛式、Y-T 等</p></div><button class="quiet" onclick="selectWarmEight()">整套選取</button></div>`:''}</div><div id="search-scope" class="mini muted gap-sm" ${state.query?'':'hidden'}>搜尋全部類型與部位；原分類已暫時略過。</div><div class="row between gap"><h2 id="catalog-title">可選動作</h2><span id="catalog-count" class="small muted"></span></div><div class="catalog-list gap-sm" id="catalog"></div><p class="mini muted gap-sm">跨部位選擇會保留；點 ☆ 收藏，之後可快速找到。</p>`;}
function filterCatalog(q){state.query=q;paintCatalog();}
function detail(){const context=state.editItem,day=doseDay(),d=day[context.phase][context.index];headerTop(context.origin==='import'?'17-import-adjust':'04-manual','回到編輯');const n=d[1].match(/\d+/g)||[1,6];footer('儲存修改','!saveDose()');return head('編輯動作',(context.origin==='import'?'副本第 '+(state.day+1)+' 天 · '+displayDate(state.mapped[state.day]):day.date)+' · '+phaseLabel(context.phase))+`<div class="card"><span class="badge">計畫劑量</span><h2 class="gap-sm">${esc(d[0])}</h2><p class="small muted gap-sm">設定計畫組次；實際重量與完成紀錄在「今天」填寫。</p><div class="formrow gap"><label>組數<input id="dose-sets" class="input" type="number" value="${n[0]}" min="1" max="5"></label><label>每組次數<input id="dose-reps" class="input" type="number" value="${n[1]||6}" min="1" max="120"></label><label>組間休息（秒）<input id="dose-rest" class="input" type="number" value="${d[2]??90}" min="0" max="300"></label><label>安排階段<select id="dose-phase" class="input">${['warm','main','cool'].map(p=>`<option value="${p}" ${context.phase===p?'selected':''}>${phaseLabel(p)}</option>`).join('')}</select></label></div><div class="divider"></div><button class="details-link" onclick="toast('動作教學在正式版本展開，不更動組次')">動作教學與準備組 ${I('arrow')}</button></div><div class="card gap"><h3>調整順序</h3><div class="row gap-sm"><button class="btn secondary grow" onclick="moveDose(-1)" ${context.index===0?'disabled':''}>↑ 往前</button><button class="btn secondary grow" onclick="moveDose(1)" ${context.index===day[context.phase].length-1?'disabled':''}>↓ 往後</button></div></div><button class="quiet gap" style="color:var(--red)" onclick="removeDose()">移除這個動作</button>`;}
function autoGoals(){headerTop('03b-dates-auto');footer('下一步：身體感受','!saveAutoConditions();go("09-auto-body")');return progress(2,true)+head('這週，希望怎麼練？','先填主要條件，動作可以交給系統搭配。','自動排課 · 10/19 — 10/25')+`<label class="label">主要方向</label><div class="goals">${['均衡體能','整體肌力','協調與反應','穩定與控制'].map((x,i)=>`<button aria-pressed="${state.goal===i}" class="goal ${state.goal===i?'on':''}" onclick="state.goal=${i};render()">${state.goal===i?'✓ ':''}${x}</button>`).join('')}</div><div class="row between gap"><label class="strong">每天可用多久？</label><div class="row"><input aria-label="每日可用分鐘" class="input" style="width:78px" type="number" id="available-minutes" oninput="state.minutes=Number(this.value)" value="${state.minutes||40}"><span class="small">分鐘</span></div></div><p class="mini muted gap-sm">訓練日合理分配，球日與恢復日可以較短。</p><label class="label gap">這週哪幾天打羽球？</label><div class="days">${['一','二','三','四','五','六','日'].map((d,i)=>`<button aria-pressed="${state.court.has(i+1)}" class="${state.court.has(i+1)?'on':''}" onclick="state.court.has(${i+1})?state.court.delete(${i+1}):state.court.add(${i+1});render()">${d}</button>`).join('')}</div><div class="row gap-sm"><span class="small muted">每次約</span><input class="input" style="width:80px" type="number" id="court-minutes" oninput="state.courtMinutes=Number(this.value)" aria-label="每次羽球分鐘" value="${state.courtMinutes||90}"><span class="small muted">分鐘</span><select class="input grow" aria-label="球局強度"><option>混合強度</option><option>輕鬆打</option><option>高強度</option></select></div><label class="label gap">可用器材</label><div class="chips">${['啞鈴','彈力繩','滑輪','滾筒','跳繩'].map(x=>chip(x,state.equipment.has(x),`toggleEquipment('${x}')`)).join('')}</div><button class="details-link gap-sm" onclick="toast('展開每週體能可用日與賽事日期')">體能可用日與比賽日期 ${I('arrow')}</button>`;}
function autoBody(){headerTop('08-auto-goals');footer('產生課表預覽','!state.mode="auto";go("10a-auto-preview")',state.health&&state.recovery!==null?'條件已確認':'請先回答恢復與疼痛狀態','',state.health!=='none'||state.recovery===null);return progress(3,true)+head('開始前，身體感覺如何？','這些資訊會影響訓練與恢復安排。')+`<label class="label">目前的恢復狀態</label><div class="stack">${[['精神正常','維持一般起步安排'],['有點累','保留拉伸，減少正式訓練'],['明顯疲勞','只做舒緩活動或休息']].map((x,i)=>`<button class="radio ${state.recovery===i?'on':''}" onclick="state.recovery=${i};render()"><span class="circle"></span><span><b>${x[0]}</b><p>${x[1]}</p></span></button>`).join('')}</div><div class="card gap"><h3>目前有疼痛、治療或動作限制嗎？</h3><div class="chips gap-sm">${[['none','沒有'],['yes','有'],['unknown','不確定']].map(([v,t])=>chip(t,state.health===v,`state.health='${v}';render()`)).join('')}</div>${state.health==='yes'||state.health==='unknown'?'<p class="small" style="color:var(--amber);margin-top:8px">需先確認允許的活動，不能直接當成一般肌力課。</p>':''}</div><div class="card gap"><h3>想加強哪裡？ <span class="small muted">選填，最多 4 項</span></h3><p class="mini muted gap-sm">前鋸肌：肩胛向前滑動的控制，可先略過。</p><div class="chips gap-sm">${['前鋸肌','肩胛穩定','臀肌','核心'].map(x=>chip(x,state.focusAreas.includes(x),`togglePreference('focusAreas','${x}')`)).join('')}</div><button class="details-link" onclick="toast('細分部位會在正式版本展開；前鋸肌可在肌力→肩胛找到')">選其他部位 ${I('arrow')}</button><div class="divider"></div><label class="label">無痛、但感覺僵硬的位置</label><div class="chips">${['胸椎','髖','肩胸','踝小腿'].map(x=>chip(x,state.stiffAreas.includes(x),`togglePreference('stiffAreas','${x}')`)).join('')}</div></div><button class="details-link gap" onclick="openPicker('auto')">想指定某些動作？ <span>${state.prefs.length?'已選 '+state.prefs.length+' 個':'尚未指定，可略過'} ›</span></button><p class="mini muted">預覽會交代手選動作是否排入，以及未排原因。</p>`;}
function planDays(imported=false){return (imported?sharedSource():manualDays()).map((d,i)=>`<button class="plan-day" onclick="state.day=${i};go('${imported?'12b-shared-day':'04b-day-view'}')"><div class="row"><span class="number">${i+1}</span><div class="grow"><h3>${imported?'第 '+(i+1)+' 天':d.date+' '+d.weekday} · ${esc(d.title)}</h3><p class="small muted gap-sm">${d.kind} · ${demoMinutes(d)} 分鐘 · ${phaseSummary(d)}</p></div>${I('arrow')}</div></button>`).join('');}
function preview(){const auto=state.mode==='auto';const list=auto?weekSource():manualDays();headerTop(auto?'09-auto-body':'04-manual','返回修改');footer('套用到課表','!applyDraft()',`${list.length} 天 · 尚未套用`,'確認後才更新日期安排');return progress(auto?4:3,auto)+head('先檢查，再套用',auto?'10/19 — 10/25 · 共 7 個日期':`10/19 起 · 共 ${list.length} 天`)+`<div class="row between"><span class="badge purple">${auto?'自動排課':'手動排課'} · 草稿預覽</span><button class="quiet" onclick="prepareShare();go('11-share')">${I('share')} 分享預覽</button></div><div class="card gap"><div class="panel-title">這份課表的重點</div><h2>${auto?'2 天肌力、3 天恢復、2 天休息':`你安排的 ${list.length} 天課表`}</h2><p class="small muted gap-sm">${auto?'可用 '+(state.minutes||40)+' 分鐘；球日保留舒緩活動，實際時間依每日理由安排。':'依你的選擇安排；可再調整動作、組次與日期。'}</p><div class="divider"></div><button class="details-link" onclick="toast('展開八區的實際安排日期')">${auto||list.some(d=>d.warm?.some(x=>x[0].includes('八段')))?'拉伸 8 / 8 區已安排':'查看拉伸分布與未安排區域'} ${I('arrow')}</button>${state.prefs.length?`<button class="details-link" onclick="toast('手選採用明細在正式版本依排課結果計算')">查看 ${state.prefs.length} 個手選動作的採用結果 ${I('arrow')}</button>`:auto?'<p class="small muted">未指定動作，由系統依條件搭配。</p>':'<p class="small muted">已保留你的手動選擇，套用前可再修改。</p>'}</div><div class="card gap">${list.map((d,i)=>`<button class="plan-day" onclick="state.day=${i};state.readContext='draft';go('04b-day-view')"><div class="row between"><div class="grow"><h3>${d.date} ${d.weekday} · ${esc(d.title)}</h3><p class="small muted gap-sm">${d.kind} · ${demoMinutes(d)?demoMinutes(d)+' 分鐘':d.kind==='休息'?'不另排體能':'尚未加入動作'}${d.kind==='恢復'?' · 當天另有羽球':''}</p></div>${I('arrow')}</div></button>`).join('')}</div><button class="quiet gap-sm" onclick="go('04-manual')">${I('edit')} 手動調整這份預覽</button><p class="mini muted gap-sm">預覽不是完成紀錄。已有訓練紀錄的日期會保留，套用前會再檢查衝突。</p>`;}
function share(){headerTop(state.shareReturn||(state.mode==='auto'?'10a-auto-preview':'10-plan-preview'),'返回課表');if(state.shareReady&&!state.shareSnapshot)createSharePreview(false);footer(state.shareReady?'複製分享連結':'建立分享連結',state.shareReady?'!toast("原型示意：此連結沒有公開服務，請用接收者預覽查看")':'!createSharePreview()',`分享 ${state.shareDays.size} 天`,state.shareReady?'分享的是固定副本':'接收者可自行選擇套用日期',!state.shareDays.size);return head('分享課表',state.shareOverride?'分享這份命名課表的副本。':'挑選要分享的天數，不必分享整週。')+`<label class="label" for="share-title">課表名稱</label><input id="share-title" class="input" maxlength="40" aria-label="分享課表名稱" value="${esc(shareName())}" oninput="state.shareTitle=this.value" ${state.shareReady?'readonly':''}><div class="card gap">${sharePool().map((d,i)=>`<button class="catalog-row" ${state.shareReady?'disabled':''} onclick="state.shareDays.has(${i})?state.shareDays.delete(${i}):state.shareDays.add(${i});render()"><span class="check ${state.shareDays.has(i)?'checked':''}">${state.shareDays.has(i)?'✓':''}</span><span class="grow"><b>${state.shareOverride?'單日課表':esc(d.date)+' '+esc(d.weekday)} · ${esc(d.title)}</b><span class="catalog-meta">${demoMinutes(d)} 分鐘</span></span></button>`).join('')}</div><div class="soft gap"><h3>分享內容</h3><p class="small muted gap-sm">只包含名稱、動作、計畫組次、休息與順序。<br>不包含健康備註、實際重量或完成紀錄。</p></div>${state.shareReady?`<div class="card gap"><span class="badge green">✓ 分享連結示例已建立</span><div class="linkbox gap-sm">https://fitness.example/s/7Q2M</div><p class="mini muted gap-sm">這是當下的固定副本，之後修改收藏不會改變已分享內容。原型連結不可對外使用。</p><button class="quiet" onclick="state.templateApplying=false;go('12-shared-view')">查看接收者會看到的畫面 ›</button><button class="quiet full" onclick="state.shareReady=false;state.shareSnapshot=null;render()">調整分享內容</button></div>`:`<p class="small muted gap">對方會看到 ${state.shareDays.size} 天內容，並自行挑選新日期。</p>`}`;}
function shared(){headerTop(null);footer('選日期，匯入我的課表','!initMapping();go("13-import-dates")');return `<div class="hero-share"><div class="kicker">朋友分享的課表</div><h1>${esc(shareName())}</h1><p class="muted small gap-sm">${sharedSource().length} 天安排 · ${sharedPhases()}</p><div class="stats"><div><b>${sharedSource().length}</b><span>天課表</span></div><div><b>${sharedTimeLabel()}</b><span>分鐘／天</span></div><div><b>${requiredEquipment(sharedSource()).filter(x=>x!=='徒手').length}</b><span>種器材</span></div></div></div><div class="read-two gap"><div><h2>先看看內容</h2><div class="card gap-sm">${planDays(true)}</div></div><aside><div class="card gap"><h3>需要準備</h3><div class="chips gap-sm">${requiredEquipment(sharedSource()).map(e=>`<span class="badge">${e}</span>`).join('')}</div><p class="small muted gap-sm">匯入前可以更換不適合的動作。</p></div><div class="soft gap"><h3>日期由你決定</h3><p class="small muted gap-sm">這是課表副本，不會自動加入行事曆。<br>下一步可逐天選日期；修改不影響分享者。</p></div><p class="small muted gap">免登入即可預覽。匯入後可保存在這台裝置。</p></aside></div>`;}
function mapping(){headerTop(state.templateApplying?'22-template-detail':'12-shared-view','返回預覽');const rows=sharedSource();footer('下一步：檢查日期','!checkMapping()',`要匯入 ${rows.length} 天`,'每一天對應一個日期');return `<div class="subnav"><span class="current">1 選日期</span><i></i><span>2 檢查並匯入</span></div>`+head(`這 ${rows.length} 天，要排在哪天？`,'每個來源日都會明確對應你的日期。')+`<div class="segments"><button aria-pressed="${state.dateMode===0}" class="${state.dateMode===0?'on':''}" onclick="state.dateMode=0;render()">保留原本間隔</button><button aria-pressed="${state.dateMode===1}" class="${state.dateMode===1?'on':''}" onclick="state.dateMode=1;render()">逐天指定日期</button></div>${state.dateMode===0?'<label class="label gap" for="import-start">第 1 天，從哪天開始？</label><input id="import-start" class="input" type="date" value="'+state.mapped[0]+'" onchange="setStart(this.value)"><p class="small muted gap-sm">改開始日，其他日期會按原間隔一起移動。想單獨改，請選「逐天指定日期」。</p>':'<p class="small muted gap-sm">每一列可單獨修改；其他日期不會跟著變動。</p>'}<div class="stack gap">${rows.map((d,i)=>`<div class="map"><div class="mapped-grid"><div class="map-head"><span class="number">${i+1}</span><div><h3>第 ${i+1} 天 · ${esc(d.title)}</h3><p class="small muted">${d.time} 分鐘</p></div></div><div class="arrow">套用到 ↓</div><div>${state.dateMode===1?`<input aria-label="第 ${i+1} 天套用日期" class="input" type="date" value="${state.mapped[i]}" onchange="setMapped(${i},this.value)">`:`<p class="strong">${displayDate(state.mapped[i])}</p>`}${dateHint(i)}</div></div></div>`).join('')}</div><p class="small muted gap">下一步會先檢查日期，不會立刻寫入。取消匯入不更動原有課表。</p>`;}
function conflicts(){headerTop('13-import-dates','返回日期');const rows=sharedSource(),problems=mappingProblems(),indices=(state.conflictIndices||[1,2]).filter(i=>i<rows.length);footer(problems.length?'請先處理日期':'查看匯入確認','15-import-review',problems.length?`${problems.length} 天仍需處理`:'✓ 日期已確認','不會自動合併或覆蓋紀錄',!!problems.length);return head(problems.length?`有 ${problems.length} 天需要先處理`:'日期衝突已處理','先選處理方式，再查看最後確認。')+indices.map(i=>{const protectedDate=state.conflictTypes?.[i]==='recorded'||i===2&&!state.conflictTypes;const oldDate=protectedDate?'10/30':'10/28';const currentlyBad=mappingProblems().includes(i);return `<div class="card gap" ${protectedDate?'style="border-color:#bd7e88"':''}><span class="badge ${protectedDate?'red':'amber'}">第 ${i+1} 天 · ${protectedDate?'已有訓練紀錄':'日期已有課表'}</span><h2 class="gap-sm">${protectedDate?'10/30 的紀錄會保留':'10/28 已有「上肢肌力」'}</h2><p class="small muted gap-sm">${protectedDate?'不能覆蓋，請替這天改日期。':'尚未開始，沒有訓練紀錄。'}</p>${!protectedDate?`<div class="stack gap"><button class="radio ${state.replaceFor!==i?'on':''}" aria-pressed="${state.replaceFor!==i}" onclick="state.replaceFor=null;render()"><span class="circle"></span><span><b>換日期，保留原課表</b></span></button><button class="radio ${state.replaceFor===i?'on':''}" aria-pressed="${state.replaceFor===i}" onclick="state.replaceFor=${i};state.mapped[${i}]='2026-10-28';render()"><span class="circle"></span><span><b>改為替換「上肢肌力」</b><p>只有按最後確認才會更動</p></span></button></div>`:''}${state.replaceFor!==i||protectedDate?`<label class="label gap" for="conflict-${i}">第 ${i+1} 天的新日期</label><input id="conflict-${i}" class="input" type="date" value="${state.mapped[i]&&displayDate(state.mapped[i])!==oldDate?state.mapped[i]:''}" onchange="setMapped(${i},this.value)">`:''}${currentlyBad?dateHint(i):''}${!currentlyBad?`<p class="mini gap-sm" style="color:var(--green)">✓ ${displayDate(state.mapped[i])} 已確認</p>`:''}</div>`;}).join('');}
function importReview(){headerTop('13-import-dates','修改日期');const list=importDays(),replaced=state.replaceFor!==null&&state.mapped[state.replaceFor]==='2026-10-28';footer(`確認匯入 ${list.length} 天課表`,'16-import-done',`新增 ${list.length-(replaced?1:0)} 天${replaced?' · 替換 1 天':''}`,'確認後才更新我的課表',!!mappingProblems().length);return `<div class="subnav"><span>1 選日期</span><i></i><span class="current">2 檢查並匯入</span></div>`+head('最後確認，才會匯入',shareName())+`<div class="card">${list.map((d,i)=>`<div class="plan-day"><div class="row between"><span class="badge gray">第 ${i+1} 天</span><span class="badge ${i===state.replaceFor&&replaced?'amber':'green'}">${i===state.replaceFor&&replaced?'替換原課表':'新增'}</span></div><h3 class="gap-sm">${esc(d.title)}</h3><p class="small muted gap-sm">→ ${displayDate(state.mapped[i])} · ${d.time} 分鐘</p>${i===state.replaceFor&&replaced?'<p class="small" style="color:var(--amber);margin-top:6px">原課表：「上肢肌力」（未有紀錄）</p>':''}</div>`).join('')}</div>${replaced?'<div class="notice gap"><b>只替換 10/28 尚未開始的「上肢肌力」。</b><br>10/30 已有紀錄，會保留不變。</div>':'<div class="success gap">✓ 不覆蓋任何既有課表或訓練紀錄。</div>'}<div class="soft gap"><div class="row between"><h3>器材已確認</h3><span style="color:var(--green)">✓</span></div><p class="small muted gap-sm">啞鈴、彈力繩、滑輪符合範例設定。</p><button class="details-link" onclick="state.pickerOrigin='import';go('17-import-adjust')">匯入前調整這份副本 ${I('arrow')}</button></div><p class="small muted gap">未登入：正式功能會將副本儲存在目前裝置；此原型不寫入。可稍後登入同步；匯入不會把動作標成完成。</p>`;}
function done(){headerTop();const rows=importDays();footer('查看我的課表','01-week');return `<div style="text-align:center">${head(`已匯入 ${rows.length} 天課表`,'完成畫面示例；此原型未實際儲存或匯入課表。')}<div class="stepdone">✓</div></div><div class="card gap">${rows.map((d,i)=>`<div class="done-date"><p class="strong">${displayDate(state.mapped[i])} · ${esc(d.title)}</p><p class="small muted">${d.time} 分鐘 · 尚未完成訓練</p></div>`).join('')}</div><div class="success gap">✓ 分享者的原課表不受影響<br>✓ 10/30 的訓練紀錄已保留</div><button class="quiet gap" onclick="toast('撤銷這次匯入，還原未有新紀錄的日期；已有新紀錄的日期會保留')">撤銷這次匯入</button><p class="small muted gap-sm">開始訓練後有新紀錄的日期，不會被撤銷覆蓋。</p><div class="card gap"><h3>需要跨裝置使用？</h3><p class="small muted gap-sm">可稍後登入並同步，不影響這次匯入。</p><button class="quiet" onclick="toast('原型示意：登入並同步')">登入並同步 ›</button></div>`;}
function render(){let el=document.getElementById('app');el.className='main';let content='';switch(current){case'01-week':content=week();break;case'02-empty':content=week(true);break;case'03-dates-manual':state.mode='manual';content=dates();break;case'03b-dates-auto':state.mode='auto';content=dates(true);break;case'04-manual':state.pickerOrigin='manual';content=editor();break;case'04b-day-view':content=readDay(false);break;case'05-pick-strength':content=picker(false);break;case'06-pick-stretch':content=picker(true);break;case'07-exercise-detail':content=detail();break;case'08-auto-goals':content=autoGoals();break;case'09-auto-body':content=autoBody();break;case'10-plan-preview':content=preview();break;case'10a-auto-preview':state.mode='auto';content=preview();break;case'11-share':content=share();break;case'11b-share-ready':state.shareReady=true;content=share();break;case'12-shared-view':content=shared();break;case'12b-shared-day':content=readDay(true);break;case'13-import-dates':content=mapping();break;case'14-import-conflict':content=conflicts();break;case'15-import-review':content=importReview();break;case'15b-import-replace':content=importReview();break;case'16-import-done':content=done();break;case'17-import-adjust':content=importAdjust();break;case'18-selected-exercises':content=selectedExercises();break;case'19-copy-day':content=copyDay();break;case'20-save-template':content=saveTemplateForm();break;case'21-my-templates':content=templateLibrary();break;case'22-template-detail':content=templateDetail();break;default:content=week();}if(!['01-week','02-empty','04-manual','04b-day-view','12-shared-view'].includes(current))el.classList.add('narrow');if(state.templateApplying&&['13-import-dates','14-import-conflict','15-import-review','16-import-done','17-import-adjust'].includes(current)){content=content.replaceAll('匯入','套用').replaceAll('分享者的原課表','我的收藏課表');document.querySelectorAll('#bottom button').forEach(b=>b.textContent=b.textContent.replaceAll('匯入','套用'));}el.innerHTML='<p class="mini muted" style="margin:0 0 18px;padding:10px 12px;border:1px dashed #91a5bd;border-radius:8px" role="note">設計原型 · 範例操作不會更新正式帳號資料。</p>'+content;document.body.dataset.page=current;if(['05-pick-strength','06-pick-stretch'].includes(current))paintCatalog();document.title=current+'｜Fitness Planner 設計原型';}

function saveAutoConditions(){state.minutes=Number(document.querySelector('#available-minutes')?.value)||40;state.courtMinutes=Number(document.querySelector('#court-minutes')?.value)||90;}
function saveDose(){const sets=Number(document.querySelector('#dose-sets').value),reps=Number(document.querySelector('#dose-reps').value),rest=Number(document.querySelector('#dose-rest').value),phase=document.querySelector('#dose-phase').value;if(!Number.isInteger(sets)||sets<1||sets>5||!Number.isInteger(reps)||reps<1||reps>120||rest<0||rest>300){toast('請填入有效組次與休息時間');return;}const c=state.editItem,day=doseDay(),row=day[c.phase][c.index];row[1]=sets+'組 × '+reps+'下';row[2]=rest;if(phase!==c.phase){day[c.phase].splice(c.index,1);day[phase].push(row);}go(c.origin==='import'?'17-import-adjust':'04-manual');toast('已更新這個動作的計畫組次');}
function weekSource(){return [{...base[0],date:'10/19',weekday:'週一'}, {date:'10/20',weekday:'週二',title:'八段舒緩拉伸',time:12,kind:'恢復'}, {...base[1],date:'10/21',weekday:'週三'}, {date:'10/22',weekday:'週四',title:'八段舒緩拉伸',time:12,kind:'恢復'}, {...base[2],date:'10/23',weekday:'週五'}, {date:'10/24',weekday:'週六',title:'休息',time:0,kind:'休息'}, {date:'10/25',weekday:'週日',title:'休息',time:0,kind:'休息'}].map(d=>({...d,warm:d.warm|| (d.kind==='恢復'?[['八段動態拉伸','1輪 · 10分鐘']]:[]),main:d.main||[],cool:d.cool||[]}));}
function dIndex(date){return date==='10/21'?1:date==='10/23'?2:0;}
function sharePool(){return state.shareOverride|| (state.mode==='auto'?weekSource():manualDays());}
function sharedSource(){return state.shareSnapshot?.days||sharePool().filter((_,i)=>state.shareDays.has(i));}
function displayDate(value){return value?value.slice(5).replace('-','/'):'請選日期';}
function dateHint(i){const value=state.mapped[i];if(!value||value<'2026-10-19')return '<p class="mini gap-sm" style="color:var(--red)">請選今天起的有效日期</p>';if(value==='2026-10-30')return '<p class="mini gap-sm" style="color:var(--red)">已有訓練紀錄，必須換日期</p>';if(value==='2026-10-28'&&!state.overwriting)return '<p class="mini gap-sm" style="color:var(--amber)">已有未開始課表，下一步處理</p>';if(state.mapped.indexOf(value)!==i)return '<p class="mini gap-sm" style="color:var(--red)">日期重複，請選不同日期</p>';return '<p class="mini gap-sm" style="color:var(--green)">✓ 可安排</p>';}
function mappingProblems(){return sharedSource().map((_,i)=>i).filter(i=>!state.mapped[i]||state.mapped[i]<'2026-10-19'||state.mapped[i]==='2026-10-30'||state.mapped[i]==='2026-10-28'&&state.replaceFor!==i||state.mapped.indexOf(state.mapped[i])!==i);}
function setMapped(i,value){state.mapped[i]=value;state.dateMode=1;render();}
function setStart(value){mapFromStart(value);render();}
function checkMapping(){const invalid=sharedSource().some((_,i)=>!state.mapped[i]||state.mapped[i]<'2026-10-19'||state.mapped.indexOf(state.mapped[i])!==i);if(invalid){toast('請先填入今天起、彼此不同的有效日期');return;}state.conflictIndices=mappingProblems();state.conflictTypes=Object.fromEntries(state.conflictIndices.map(i=>[i,state.mapped[i]==='2026-10-30'?'recorded':'planned']));go(state.conflictIndices.length?'14-import-conflict':'15-import-review');}
function cancelImport(){state.mapped=['2026-10-26','2026-10-28','2026-10-30'];state.overwriting=false;state.replaceFor=null;const own=state.templateApplying;state.templateApplying=false;go(own?'22-template-detail':'12-shared-view');toast('已取消；原有課表沒有變更');}
function saveDraft(){state.draftSaved=true;try{localStorage.setItem('fitness_planner_design_draft',JSON.stringify({days:manualDays(),dates:[...state.dates]}));}catch{}go('01-week');toast('已保留這台裝置上的排課草稿');}
function openPicker(origin){state.pickerOrigin=origin;state.selected=new Set();state.query='';state.favoritesOnly=false;state.use='strength';state.region='腿';go('05-pick-strength');}
function readDay(shared=false){const draft=!shared&&state.readContext==='draft',rows=shared?sharedSource():draft?(state.mode==='auto'?weekSource():manualDays()):state.applied||weekSource(),d=rows[state.day]||rows[0];headerTop(shared?'12-shared-view':draft?(state.mode==='auto'?'10a-auto-preview':'10-plan-preview'):'01-week',shared?'返回分享預覽':draft?'返回草稿預覽':'返回課表');footer(shared?'選日期，匯入這份課表':draft?'返回檢查課表':'開始這天的訓練',shared?'!initMapping();go("13-import-dates")':draft?(state.mode==='auto'?'10a-auto-preview':'10-plan-preview'):'!toast("原型示意：正式版本會進入今天的訓練流程")');return head(shared?`第 ${state.day+1} 天 · ${d.title}`:`${d.date} ${d.weekday} · ${d.title}`,`${demoMinutes(d)} 分鐘 · ${phaseSummary(d)}`)+`<div class="row between"><span class="badge ${shared||draft?'purple':''}">${shared?'分享副本 · 唯讀預覽':draft?'草稿預覽 · 尚未套用':'已安排 · 尚未完成'}</span>${shared?'':`<button class="quiet" onclick="editReadDay()">編輯安排</button>`}</div>${shared?'':dayTemplateActions(d,'04b-day-view')}<div class="card gap">${['warm','main','cool'].filter(p=>d[p]?.length).map(p=>`<h2 class="gap-sm">${phaseLabel(p)}</h2>${readEx(d[p])}`).join('')||'<p class="small muted">休息，不另安排體能。</p>'}</div><p class="small muted gap">${shared?'這裡只看內容；匯入你的副本後再編輯，分享者不受影響。':draft?'這是剛安排的草稿，回到檢查頁確認後才會套用。':'點詳情或長按查看教學。編輯會先成為草稿，確認後才更新。'}</p>`;}
function readEx(items){return items.map((x,i)=>`<div class="exercise"><span class="count">${i+1}</span><div class="grow"><b>${x[0]}</b><p>${x[1]}</p></div><button class="dots" onclick="toast('展開這個動作的步驟與組次；唯讀，不改課表')">詳情</button></div>`).join('');}
function importAdjust(){headerTop('15-import-review','回到匯入確認');const rows=importDays();state.day=Math.min(state.day,rows.length-1);const d=rows[state.day];footer('儲存並回到匯入確認','!go("15-import-review");toast("已保留副本調整，尚未匯入")');return head('調整匯入副本','只調整你的副本，不改分享者的原課表。')+`<div class="daytabs">${rows.map((d,i)=>`<button aria-pressed="${state.day===i}" class="${state.day===i?'on':''}" onclick="state.day=${i};render()">第 ${i+1} 天<br>${displayDate(state.mapped[i])}</button>`).join('')}</div><div class="card"><h2>${esc(d.title)}</h2>${['warm','main','cool'].map(p=>`<div class="phase-title gap"><h3>${phaseLabel(p)}</h3><button class="quiet" onclick="openImportPicker('${p}')">＋ 加入動作</button></div>${exrows(d[p]||[],p,'import')}`).join('')}</div><div class="soft gap small">修改後會回到同一份匯入確認，不會跳去手動排課草稿。</div>`;}


function manualDays(){return [...state.dates].sort((a,b)=>a-b).map((n,i)=>state.manualDraft?.[n]||base.find(d=>d.date==='10/'+n)||{date:'10/'+n,weekday:'週'+['日','一','二','三','四','五','六'][new Date('2026-10-'+n+'T12:00:00Z').getUTCDay()],title:'自訂訓練',time:0,kind:'自訂',warm:[],main:[],cool:[]});}
function editorDay(){return manualDays()[state.day]||base[0];}
function demoMinutes(day){return day.time||day.warm.length*2+day.main.length*3+day.cool.length*2;}
function createManualDraft(){state.day=0;state.manualDraft=Object.fromEntries([...state.dates].map(n=>[n,{date:'10/'+n,weekday:'週'+['日','一','二','三','四','五','六'][new Date('2026-10-'+n+'T12:00:00Z').getUTCDay()],title:'自訂訓練',time:0,kind:'自訂',warm:[],main:[],cool:[]}]));go('04-manual');}
function openManualPicker(phase){state.pickerOrigin='manual';state.phase=phase;state.use=phase==='main'?'strength':phase==='cool'?'release':'stretch';state.region=phase==='main'?'腿':'全部';state.selected=new Set();state.query='';state.favoritesOnly=false;go(phase==='main'?'05-pick-strength':'06-pick-stretch');}
function addFlow(){editorDay().warm.push(['八段動態拉伸','1輪 · 10分鐘']);render();toast('已加入暖身草稿');}
function prepareShare(){state.templateApplying=false;state.shareReturn=null;state.shareOverride=null;state.shareSnapshot=null;state.shareTitle='';state.shareReady=false;state.shareDays=new Set(sharePool().map((d,i)=>d.kind!=='休息'?i:null).filter(i=>i!==null));}
function mapFromStart(value){const start=new Date(value+'T12:00:00Z');if(Number.isNaN(+start))return;const first=Number(sharedSource()[0].date.split('/')[1]);state.mapped=sharedSource().map(d=>new Date(+start+(Number(d.date.split('/')[1])-first)*86400000).toISOString().slice(0,10));state.replaceFor=null;}
function initMapping(){state.importCopy=structuredClone(sharedSource());mapFromStart('2026-10-26');state.dateMode=0;state.day=0;}


function toggleEquipment(value){state.equipment.has(value)?state.equipment.delete(value):state.equipment.add(value);render();}
function requiredEquipment(rows){const names=rows.flatMap(d=>['warm','main','cool'].flatMap(p=>d[p]||[]).map(x=>x[0])).join(' ');const found=['啞鈴','彈力繩','滑輪','滾筒','跳繩'].filter(x=>names.includes(x));return found.length?found:['徒手'];}
function phaseLabel(p){return {warm:'暖身',main:'訓練',cool:'收操'}[p];}
function phaseSummary(d){return ['warm','main','cool'].filter(p=>d[p]?.length).map(phaseLabel).join(' → ')|| (d.kind==='休息'?'休息':'尚未加入動作');}
function openDose(phase,index,origin='manual'){state.editItem={phase,index,origin};go('07-exercise-detail');}
function doseDay(){return state.editItem.origin==='import'?importDays()[state.day]:editorDay();}
function moveDose(delta){const c=state.editItem,rows=doseDay()[c.phase],next=c.index+delta;if(next<0||next>=rows.length)return;[rows[c.index],rows[next]]=[rows[next],rows[c.index]];c.index=next;render();}
function removeDose(){const c=state.editItem;doseDay()[c.phase].splice(c.index,1);go(c.origin==='import'?'17-import-adjust':'04-manual');toast('已從這份草稿移除動作');}
function importDays(){if(!state.importCopy)state.importCopy=structuredClone(sharedSource());return state.importCopy;}
function openImportPicker(phase){state.pickerOrigin='import';state.phase=phase;state.selected=new Set();state.query='';state.favoritesOnly=false;state.use=phase==='main'?'strength':phase==='cool'?'release':'stretch';state.region=phase==='main'?'腿':'全部';go('05-pick-strength');}
function togglePreference(key,value){state[key]=state[key].includes(value)?state[key].filter(x=>x!==value):[...state[key],value];render();}
function editReadDay(){const rows=structuredClone(state.readContext==='draft'?(state.mode==='auto'?weekSource():manualDays()):state.applied||weekSource());state.dates=new Set(rows.map(d=>Number(d.date.split('/')[1])));state.manualDraft=Object.fromEntries(rows.map(d=>[Number(d.date.split('/')[1]),d]));state.mode='manual';go('04-manual');}
function applyDraft(){state.draftSaved=false;try{localStorage.removeItem('fitness_planner_design_draft');}catch{}state.applied=structuredClone(state.mode==='auto'?weekSource():manualDays());state.autoApplied=true;state.readContext='saved';go('01-week');}
function restoreDraft(){try{const saved=JSON.parse(localStorage.getItem('fitness_planner_design_draft'));if(!saved?.days?.length)return;state.dates=new Set(saved.dates);state.manualDraft=Object.fromEntries(saved.days.map(d=>[Number(d.date.split('/')[1]),d]));state.draftSaved=true;}catch{}}


function warmRows(rows){return rows.length>3?`<details class="phase-fold"><summary>${rows.length} 個動作 · 展開查看</summary><p class="mini muted gap-sm">${esc(rows.slice(0,2).map(x=>x[0]).join('、'))}等</p>${exrows(rows,'warm')}</details>`:exrows(rows,'warm');}
function pickerBack(){return state.pickerOrigin==='auto'?'09-auto-body':state.pickerOrigin==='import'?'17-import-adjust':'04-manual';}
function pickerDay(){return state.pickerOrigin==='import'?importDays()[state.day]:editorDay();}
function refreshPicker(selector){const focused=document.activeElement,oldSelector=selector||(focused?.dataset?.id?`[data-id="${focused.dataset.id}"]`:focused?.id?'#'+focused.id:null),y=scrollY;render();scrollTo(0,y);if(oldSelector)document.querySelector(oldSelector)?.focus({preventScroll:true});}
function setPickerKind(kind){state.use=kind;state.region=kind==='strength'?'腿':'全部';state.favoritesOnly=false;refreshPicker();}
function setPickerRegion(region){state.region=region;state.favoritesOnly=false;refreshPicker();}
function toggleFavorite(id){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);refreshPicker(`[data-id="${id}"]`);toast(state.favorites.has(id)?'已收藏，之後可用「★ 收藏」找回':'已取消收藏');}
function clearPickerSearch(){state.query='';const input=document.querySelector('#search');if(input)input.value='';paintCatalog();input?.focus();}
function pickerMatches(){const q=state.query.trim().toLowerCase().replace(/\s/g,'');return exercises.filter(e=>{if(q){const extra=e.group!=='strength'?e.region==='腿部'||e.region==='踝小腿'?'腿拉伸 小腿拉伸 大腿拉伸':e.region+'拉伸':'';return (e.name+e.tags+e.equip+(e.aliases||'')+extra).toLowerCase().replace(/\s/g,'').includes(q);}return e.group===state.use&&(!state.favoritesOnly||state.favorites.has(e.id))&&(state.favoritesOnly||state.region==='全部'||e.region===state.region||state.region==='前鋸肌'&&e.tags.includes('前鋸肌'));});}
function paintCatalog(){const list=document.querySelector('#catalog');if(!list)return;const matches=pickerMatches();list.innerHTML=matches.length?catalogRows(matches):`<div class="empty small"><b>${state.favoritesOnly?'這個類型還沒有收藏':'找不到符合的動作'}</b><p>${state.favoritesOnly?'在動作旁點 ☆ 即可收藏。':'可以縮短關鍵字，或清除篩選。'}</p><button class="quiet" onclick="state.query='';state.region='全部';state.favoritesOnly=false;refreshPicker()">查看這類全部動作</button></div>`;document.querySelector('#catalog-count').textContent=matches.length+' 個';document.querySelector('#catalog-title').textContent=state.query?'搜尋結果':state.favoritesOnly?'我的收藏':'可選動作';document.querySelector('#picker-browse').hidden=!!state.query;document.querySelector('#search-scope').hidden=!state.query;}
function pickerFooter(){const n=state.selected.size;footer(`加入 ${n} 個動作`,'!addSelected()',`已選 ${n} 個`,'',!n);document.querySelector('.bottom .grow').innerHTML=`<button class="quiet selected-trigger" onclick="go('18-selected-exercises')" ${!n?'disabled':''}>已選 ${n} 個 · 查看</button><p class="mini muted">${state.pickerOrigin==='auto'?'偏好候選':state.pickerOrigin==='import'?'副本 '+displayDate(state.mapped[state.day]):pickerDay().date} · ${phaseLabel(state.phase)}</p>`;}
function selectWarmEight(){if(pickerDay().warm.some(x=>x[0]==='八段動態拉伸')){toast('這天已有每日八段暖身，可回課表查看');return;}for(const id of ['child','greatest','cat','yt','scap-push','thoracic','hips','legflow']){const e=exercises.find(x=>x.id===id);if(!pickerDay().warm.some(x=>x[0]===e.name))state.selected.add(id);}refreshPicker();toast('已選取八段暖身，按加入才放進課表');}
function selectedExercises(){headerTop(state.use==='strength'?'05-pick-strength':'06-pick-stretch','繼續選動作');const n=state.selected.size;footer(`加入 ${n} 個動作`,'!addSelected()',`${n} 個待加入`,phaseLabel(state.phase),!n);return head('確認已選動作',`${state.pickerOrigin==='auto'?'自動排課偏好':state.pickerOrigin==='import'?'副本 '+displayDate(state.mapped[state.day]):pickerDay().date+' '+pickerDay().weekday} · ${phaseLabel(state.phase)}`)+`<div class="soft small">切換分類或搜尋，都不會清掉這份選擇。<br>以下尚未加入課表，可移除後再確認。</div><div class="card gap">${[...state.selected].map((id,i)=>{const e=exercises.find(x=>x.id===id);return `<div class="exercise"><span class="count">${i+1}</span><div class="grow"><b>${esc(e.name)}</b><p>${esc(e.tags)} · ${esc(e.equip)}</p></div><button class="dots" aria-label="移除待選：${esc(e.name)}" onclick="state.selected.delete('${id}');render()">移除</button></div>`;}).join('')||'<p class="small muted">目前沒有待加入動作，可返回繼續選。</p>'}</div><p class="small muted gap">加入後可在這天調整組次與順序。</p>`;}
function cancelPicker(){if(state.selected.size&&!confirm('放棄這次尚未加入的 '+state.selected.size+' 個選擇？課表不會變更。'))return;state.selected.clear();go(pickerBack());}
function additionNotice(){const a=state.lastAddition;if(!a||a.day!==editorDay()||!a.rows.length)return '';return `<div class="success gap-sm" style="margin-bottom:18px"><div class="row between"><span>✓ ${a.rows.length} 個動作已加入 ${a.day.date} ${phaseLabel(a.phase)}</span><button class="quiet" onclick="undoAddition()">復原</button></div></div>`;}
function undoAddition(){const a=state.lastAddition;if(!a)return;a.day[a.phase]=a.day[a.phase].filter(row=>!a.rows.includes(row));state.lastAddition=null;render();toast('已復原這次加入；原本的動作保留');}
function openCopyDay(){state.copySource=state.day;state.copyPhases=new Set(['warm','main','cool'].filter(p=>editorDay()[p].length));state.copyTargets=new Set();go('19-copy-day');}
function copyAllowed(i){return i!==state.copySource&&state.copyPhases.size&&[...state.copyPhases].every(p=>!manualDays()[i][p].length);}
function copyDay(){headerTop('04-manual','回到排課');const days=manualDays(),source=days[state.copySource??state.day];footer(`複製到 ${state.copyTargets.size} 天`,'!confirmCopyDay()',`已選 ${state.copyTargets.size} 天`,'只複製計畫，不標記完成',!state.copyTargets.size||!state.copyPhases.size);return head('複製這天的安排',`${source.date} ${source.weekday} · 選要複用的階段與日期`)+`<h2>要複製哪些階段？</h2><div class="chips gap-sm">${['warm','main','cool'].filter(p=>source[p].length).map(p=>chip(phaseLabel(p),state.copyPhases.has(p),`state.copyPhases.has('${p}')?state.copyPhases.delete('${p}'):state.copyPhases.add('${p}');state.copyTargets.clear();render()`)).join('')}</div><h2 class="gap">套用到其他已選日期</h2><div class="card gap-sm">${days.map((d,i)=>i===state.copySource?'':`<button aria-label="複製到 ${d.date} ${d.weekday}" class="radio gap-sm ${state.copyTargets.has(i)?'on':''}" aria-pressed="${state.copyTargets.has(i)}" ${!copyAllowed(i)?'disabled':''} onclick="state.copyTargets.has(${i})?state.copyTargets.delete(${i}):state.copyTargets.add(${i});render()"><span class="check ${state.copyTargets.has(i)?'checked':''}">${state.copyTargets.has(i)?'✓':''}</span><span><b>${d.date} ${d.weekday}</b><p>${copyAllowed(i)?'所選階段空白，可複製':state.copyPhases.size?'所選階段已有內容，保留不覆蓋':'請先選擇階段'}</p></span></button>`).join('')}</div><div class="soft small gap">只複製到所選階段空白的日期，不合併、不覆蓋。<br>複製後每一天都能獨立調整，不會連動修改。</div>`;}
function confirmCopyDay(){const target=[...state.copyTargets];if(!target.length||target.some(i=>!copyAllowed(i)))return;const days=manualDays(),source=days[state.copySource];for(const i of target)for(const p of state.copyPhases)days[i][p]=structuredClone(source[p]);state.copyTargets.clear();go('04-manual');toast('已複製到 '+target.length+' 天草稿，各天可獨立修改');}


const TEMPLATE_KEY='fitness_planner_design_templates';
function countPlanItems(day){return ['warm','main','cool'].reduce((sum,p)=>sum+(day[p]?.length||0),0);}
function planSnapshot(day){const plan={title:String(day.title||'自訂課表'),kind:day.kind||'自訂',time:demoMinutes(day)};for(const phase of ['warm','main','cool'])plan[phase]=(day[phase]||[]).map(row=>{const result=[String(row[0]),String(row[1])];if(Number.isFinite(row[2]))result.push(row[2]);return result;});return plan;}
function loadTemplates(){try{const saved=JSON.parse(localStorage.getItem(TEMPLATE_KEY)||'[]');state.templates=Array.isArray(saved)?saved.filter(t=>typeof t.id==='string'&&/^[\w-]{1,80}$/.test(t.id)&&typeof t.name==='string'&&t.plan&&['warm','main','cool'].every(p=>Array.isArray(t.plan[p]))):[];}catch{state.templates=[];}}
function dayTemplateActions(day,back){const disabled=!countPlanItems(day);return `<div class="row between" style="margin:4px 0 14px"><button class="quiet" ${disabled?'disabled':''} onclick="openSaveTemplate('${back}')">${I('book')} 儲存為課表</button><button class="quiet" ${disabled?'disabled':''} onclick="shareCurrentDay('${back}')">${I('share')} 分享這天</button></div>`;}
function currentViewedDay(){if(current==='04-manual')return editorDay();const rows=state.readContext==='draft'?(state.mode==='auto'?weekSource():manualDays()):state.applied||weekSource();return rows[state.day]||rows[0];}
function openSaveTemplate(back){const day=currentViewedDay();if(!countPlanItems(day))return;state.templatePayload=planSnapshot(day);state.templateName=day.title==='自訂訓練'?'':day.title;state.templateError='';state.templateReturn=back;state.renamingTemplateId=null;go('20-save-template');}
function saveTemplateForm(){if(!state.templatePayload){headerTop('01-week','返回課表');footer('選一天課表','01-week');return head('先選一天課表','從當天的「儲存為課表」開始，再幫這份安排取名字。');}const rename=!!state.renamingTemplateId;headerTop(rename?'22-template-detail':state.templateReturn,'取消');footer(rename?'儲存名稱':'儲存到我的課表','!saveTemplate()',rename?'只改收藏名稱':'建立可重複使用的副本','不更動原日期安排',!state.templateName.trim());return head(rename?'重新命名課表':'把這天收藏成課表','例如：全身肌力 A、球日前動態暖身。')+`<form id="template-form" onsubmit="event.preventDefault();saveTemplate()"><label class="label" for="template-name">課表名稱</label><input id="template-name" class="input" maxlength="40" required value="${esc(state.templateName)}" aria-describedby="template-name-help template-error" aria-invalid="${!!state.templateError}" placeholder="幫這份課表取個名字" oninput="updateTemplateName(this.value)"><div class="row between gap-sm"><p id="template-name-help" class="mini muted">1–40 個字元，可之後重新命名。</p><span id="template-name-count" class="mini muted">${state.templateName.length}/40</span></div><p id="template-error" class="small gap-sm" role="alert" style="color:var(--red)">${esc(state.templateError)}</p><div class="card gap"><h2>會一起保存</h2><div class="chips gap-sm">${['warm','main','cool'].filter(p=>state.templatePayload?.[p]?.length).map(p=>`<span class="badge">${phaseLabel(p)} ${state.templatePayload[p].length} 項</span>`).join('')}</div><p class="small muted gap-sm">動作順序、計畫組次與休息。<br>不含日期、實際重量、健康備註或完成紀錄。</p></div><div class="soft gap small">收藏是一份獨立副本。這天之後改課表，不會連動修改收藏；收藏也不會被標成已完成。</div></form>`;}
function updateTemplateName(value){state.templateName=value;state.templateError='';document.querySelector('#template-name-count').textContent=value.length+'/40';document.querySelector('#template-error').textContent='';document.querySelector('#template-name').setAttribute('aria-invalid','false');document.querySelector('.bottom .btn').disabled=!value.trim();}
function saveTemplate(){const name=state.templateName.trim();let error='';if(!name||name.length>40)error='請填入 1–40 個字元的名稱。';else if(state.templates.some(t=>t.id!==state.renamingTemplateId&&t.name.toLocaleLowerCase()===name.toLocaleLowerCase()))error='已經有同名課表，請換個名稱；原收藏會保留。';if(error){state.templateError=error;render();document.querySelector('#template-name').focus();return;}const old=state.templates.find(t=>t.id===state.renamingTemplateId);const item={id:old?.id||crypto.randomUUID(),name,createdAt:old?.createdAt||new Date().toISOString(),plan:structuredClone(old?.plan||state.templatePayload)};item.plan.title=name;const next=old?state.templates.map(t=>t.id===old.id?item:t):[item,...state.templates];try{localStorage.setItem(TEMPLATE_KEY,JSON.stringify(next));}catch{state.templateError='這台裝置暫時無法儲存，請稍後重試。';render();return;}state.templates=next;state.activeTemplateId=item.id;state.renamingTemplateId=null;go('21-my-templates');toast(old?'已更新收藏名稱':'已儲存到我的課表');}
function templateLibrary(){headerTop('01-week','返回課表');nav();return head('我的課表','收藏好的安排，下次直接選日期使用。')+(!state.templates.length?`<div class="card empty"><h2>還沒有收藏課表</h2><p>排好某一天後，點「儲存為課表」，取名就能收藏。<br>單一動作的 ☆ 收藏仍留在動作庫。</p><button class="btn primary gap" onclick="go('03-dates-manual')">先排一天課表</button></div>`:`<p class="small muted">${state.templates.length} 份課表 · 這台裝置已保存</p><div class="stack gap">${state.templates.map(t=>`<button class="card full template-card" onclick="state.activeTemplateId='${t.id}';go('22-template-detail')"><span class="row between"><b>${esc(t.name)}</b>${I('arrow')}</span><span class="catalog-meta">${countPlanItems(t.plan)} 個動作 · ${demoMinutes(t.plan)} 分鐘（示例）</span><span class="chips gap-sm">${['warm','main','cool'].filter(p=>t.plan[p].length).map(p=>`<span class="badge">${phaseLabel(p)}</span>`).join('')}</span></button>`).join('')}</div><p class="mini muted gap">這是獨立原型的裝置收藏；正式 App 的登入同步尚未接入。</p>`);}
function activeTemplate(){return state.templates.find(t=>t.id===state.activeTemplateId);}
function templateDetail(){const t=activeTemplate();headerTop('21-my-templates','我的課表');if(!t){footer('回到我的課表','21-my-templates');return head('找不到這份收藏','請回清單選擇一份課表。');}footer('選日期套用','!applySavedTemplate()','單日課表副本','下一步先選日期，不會立刻寫入');return head(t.name,`${countPlanItems(t.plan)} 個動作 · ${demoMinutes(t.plan)} 分鐘（示例）`)+`<div class="row between"><span class="badge">已收藏 · 尚未指定日期</span><button class="quiet" onclick="renameSavedTemplate()">重新命名</button></div><button class="btn secondary full gap" onclick="shareSavedTemplate()">${I('share')} 分享這份課表</button><div class="card gap">${['warm','main','cool'].filter(p=>t.plan[p].length).map(p=>`<h2 class="gap-sm">${phaseLabel(p)}</h2>${readEx(t.plan[p])}`).join('')}</div><p class="small muted gap">套用後，每個日期都有自己的副本；修改某一天，不會改到這份收藏或朋友收到的分享。</p>`;}
function renameSavedTemplate(){const t=activeTemplate();state.renamingTemplateId=t.id;state.templatePayload=structuredClone(t.plan);state.templateName=t.name;state.templateError='';go('20-save-template');}
function sharedPhases(){return ['warm','main','cool'].filter(p=>sharedSource().some(d=>d[p]?.length)).map(phaseLabel).join('、')||'休息安排';}
function sharedTimeLabel(){const values=sharedSource().map(d=>demoMinutes(d)),min=Math.min(...values),max=Math.max(...values);return min===max?String(min):min+'–'+max;}
function shareName(){return state.shareSnapshot?.name||state.shareTitle.trim()||`羽球基礎・${state.shareDays.size} 天課表`;}
function setSingleShare(day,title,back){state.shareOverride=[{...planSnapshot(day),title,date:'10/19',weekday:''}];state.shareTitle=title;state.shareReturn=back;state.shareDays=new Set([0]);state.shareSnapshot=null;state.shareReady=false;state.templateApplying=false;state.importCopy=null;}
function shareSavedTemplate(){const t=activeTemplate();setSingleShare(t.plan,t.name,'22-template-detail');go('11-share');}
function shareCurrentDay(back){const day=currentViewedDay();setSingleShare(day,day.title,back);go('11-share');}
function createSharePreview(redraw=true){const name=(state.shareTitle||shareName()).trim();if(!state.shareDays.size||!name||name.length>40){toast('請填入名稱並選擇至少一天');return;}state.shareSnapshot={name,days:sharePool().filter((_,i)=>state.shareDays.has(i)).map(d=>({...planSnapshot(d),date:d.date,weekday:d.weekday}))};state.shareTitle=name;state.shareReady=true;if(redraw)render();}
function applySavedTemplate(){const t=activeTemplate();setSingleShare(t.plan,t.name,'22-template-detail');createSharePreview(false);state.templateApplying=true;initMapping();go('13-import-dates');}

loadTemplates();
const initial=new URL(location).searchParams.get('page');if(initial)current=initial;if(['01-week','04-manual'].includes(current))restoreDraft();if(['15-import-review','16-import-done','17-import-adjust'].includes(current)){state.mapped=['2026-10-26','2026-10-29','2026-10-31'];}if(current==='15b-import-replace'){state.overwriting=true;state.replaceFor=1;state.mapped=['2026-10-26','2026-10-28','2026-10-31'];}if(current==='06-pick-stretch'){state.phase='warm';state.use='stretch';state.region='胸椎';state.selected=new Set(['thoracic']);}render();
window.prototypePages=['01-week','02-empty','03-dates-manual','03b-dates-auto','04-manual','04b-day-view','05-pick-strength','06-pick-stretch','07-exercise-detail','08-auto-goals','09-auto-body','10-plan-preview','10a-auto-preview','11-share','11b-share-ready','12-shared-view','12b-shared-day','13-import-dates','14-import-conflict','15-import-review','15b-import-replace','16-import-done','17-import-adjust'];

document.addEventListener('focusin',event=>{requestAnimationFrame(()=>{const el=event.target;if(!(el instanceof HTMLElement)||el.closest('.bottom,.top,.side,.nav'))return;const box=el.getBoundingClientRect(),footer=document.querySelector('.bottom,.nav')?.getBoundingClientRect(),header=document.querySelector('.top')?.getBoundingClientRect();if(footer&&box.bottom>footer.top-10||header&&box.top<header.bottom+8)el.scrollIntoView({block:'center',behavior:'instant'});});});
